const parts = String(msg.payload).trim().split(/\s+/);
if (parts.length !== 2 || !parts.every(part => /^-?\d+(\.\d+)?$/.test(part))) return null;

const [T, H] = parts.map(Number);
if (!Number.isFinite(T) || !Number.isFinite(H) || H < 0 || H > 100) return null;

flow.set("self", { T, H });
const prefix = "gti700e2025/data/emplacements/equipe02";
return [
  { topic: prefix + "/temperature", payload: T.toFixed(1) },
  { topic: prefix + "/humidite", payload: H.toFixed(1) }
];

const topic = /^gti700e2025\/data\/emplacements\/equipe(0[1-9]|1[0-2])\/(temperature|humidite)$/;
const match = String(msg.topic).match(topic);
const text = String(msg.payload).trim();
if (!match || !/^-?\d+(\.\d+)?$/.test(text)) return null;

const [, team, metric] = match;
const key = metric === "temperature" ? "T" : "H";
const value = Number(text);
if (!Number.isFinite(value) || (key === "H" && (value < 0 || value > 100))) return null;

const group = flow.get("group") || { teams: {}, samples: {}, summary: {} };
const teamNumber = Number(team);
group.teams[team] = { ...group.teams[team], [key]: value };
const sample = group.samples[key] || { sum: 0, count: 0, min: [value, teamNumber], max: [value, teamNumber] };
sample.sum += value;
sample.count += 1;
if (value < sample.min[0]) sample.min = [value, teamNumber];
if (value > sample.max[0]) sample.max = [value, teamNumber];
group.samples[key] = sample;
group.summary[key + "min"] = sample.min;
group.summary[key + "max"] = sample.max;
group.summary[key + "moy"] = sample.sum / sample.count;
flow.set("group", group);

const latest = Object.keys(group.teams).sort().map(id => {
  const { T, H } = group.teams[id];
  const fields = {};
  if (T !== undefined) fields.Temperature = T.toFixed(1);
  if (H !== undefined) fields.Humidite = H.toFixed(1);
  return JSON.stringify(id) + ": " + JSON.stringify(fields).replace(/:/g, ": ").replace(/,/g, ", ");
});
const lines = [["T", "Température", "C"], ["H", "Humidité", "%"]].map(([k, label, unit]) => {
  const stats = group.samples[k];
  if (!stats) return label + " du groupe: aucune information disponible.";
  const show = ([n, id]) => n.toFixed(1) + unit + " [" + id + "]";
  return label + " du groupe: min:" + show(stats.min) + ", max:" + show(stats.max) +
    ", moy:" + group.summary[k + "moy"].toFixed(1) + unit + ".";
});
msg.payload = ["Dernières valeurs de température et d'humidité: [" + latest.join(", ") + "]", ...lines].join("\n");
return msg;

const entries = msg.payload.feed?.entry || msg.payload.rss?.channel?.[0]?.item || [];
const current = entries.find(item =>
  item.category?.some(category => /^Conditions actuelles$/i.test(category.$?.term || category)) ||
  /^Conditions actuelles\s*:/i.test(item.title?.[0]?._ || item.title?.[0] || "")
);
const summary = current?.summary?.[0] || current?.description?.[0] || "";
const text = String(summary._ ?? summary)
  .replace(/<br\s*\/?>/gi, "\n").replace(/<[^>]*>/g, "")
  .replace(/&(?:nbsp|#160|#8239);/gi, " ").replace(/&deg;|&#176;/gi, "°");

const temperature = text.match(/Température\s*:\s*(-?\d+(?:[.,]\d+)?)\s*°?\s*C/i);
const humidity = text.match(/Humidité\s*:\s*(\d+(?:[.,]\d+)?)\s*%/i);
const wind = text.match(/Vents?\s*:[^\r\n\d]*?(\d+(?:[.,]\d+)?)\s*km\s*\/\s*h/i);
const calm = /Vents?\s*:\s*calmes?\b/i.test(text);
if (!temperature || !humidity || (!wind && !calm)) {
  node.warn("Conditions actuelles incomplètes.");
  return null;
}

const number = match => Number(match[1].replace(",", "."));
const { T, H, V } = { T: number(temperature), H: number(humidity), V: wind ? number(wind) : 0 };
if (![T, H, V].every(Number.isFinite)) return null;
flow.set("outside", { T, H, V });
msg.payload = "Environnement Canada - Température: " + T.toFixed(1) + "C\n" +
  "Environnement Canada - Humidité: " + H.toFixed(1) + "%\n" +
  "Environnement Canada - Vitesse du vent: " + V.toFixed(1) + " km/h";
return msg;

const mode = context.get("mode") || 0;
context.set("mode", (mode + 1) % 4);
const fixed = (n, unit) => n.toFixed(1) + unit;
const team = id => String(id).padStart(2, "0");
const indoor = flow.get("self");
const outdoor = flow.get("outside");
const stats = flow.get("group")?.summary || {};
const pair = (data, prefix) => prefix + " " + fixed(data.T, "C") + ", " + fixed(data.H, "%");
const group = (key, unit) => {
  const show = ([n, id]) => fixed(n, unit) + " [" + team(id) + "]";
  if (!stats[key + "min"]) return "[2] " + key + ": indisponible";
  return "[2] " + key + "min:" + show(stats[key + "min"]) +
    ", " + key + "max:" + show(stats[key + "max"]) + ", " + key + "moy:" + fixed(stats[key + "moy"], unit);
};
const screens = [
  indoor ? pair(indoor, "[1]") : "[1] Indisponible",
  group("T", "C"),
  group("H", "%"),
  outdoor ? pair(outdoor, "[3]") + ", " + fixed(outdoor.V, " km/h") : "[3] Indisponible"
];
// La chaîne ne contient que du texte fixe et des nombres. Les guillemets la passent en un argument.
msg.payload = "'" + screens[mode] + "'";
return msg;

const indoor = flow.get("self");
const outdoor = flow.get("outside");
const { teams = {}, summary = {} } = flow.get("group") || {};
const path = msg.req.route.path;
const team = msg.req.params?.team;
const fixed = number => number.toFixed(1);
const complete = pair => pair?.T !== undefined && pair?.H !== undefined;

if (path !== "/") {
  const data = { "/self": indoor, "/outside": outdoor, "/group": summary }[path] ??
    (complete(teams[team]) ? teams[team] : {});
  msg.headers = { "content-type": "application/json; charset=utf-8" };
  const keys = path === "/group" ? ["Tmin", "Tmax", "Tmoy", "Hmin", "Hmax", "Hmoy"] : ["T", "H", "V"];
  const fields = keys.filter(key => data[key] !== undefined).map(key => {
    const value = data[key];
    const literal = Array.isArray(value) ? "[" + fixed(value[0]) + "," + value[1] + "]" : fixed(value);
    return JSON.stringify(key) + ": " + literal;
  });
  msg.payload = "{" + fields.join(", ") + "}";
  return [msg, null];
}

const missing = "aucune information disponible";
const reading = (value, unit) => value === undefined ? missing : fixed(value) + unit;
const extreme = (pair, unit) => pair ? reading(pair[0], unit) + " [équipe " +
  String(pair[1]).padStart(2, "0") + "]" : missing;
msg.headers = { "content-type": "text/html; charset=utf-8" };
msg.payload = {
  indoorT: reading(indoor?.T, "C"), indoorH: reading(indoor?.H, "%"),
  outdoorT: reading(outdoor?.T, "C"), outdoorH: reading(outdoor?.H, "%"),
  teams: Array.from({ length: 12 }, (_, i) => {
    const id = String(i + 1).padStart(2, "0");
    const pair = teams[id];
    return { id, value: complete(pair) ? reading(pair.T, "C") + ", " + reading(pair.H, "%") : missing };
  }),
  Tmin: extreme(summary.Tmin, "C"), Tmax: extreme(summary.Tmax, "C"), Tmoy: reading(summary.Tmoy, "C"),
  Hmin: extreme(summary.Hmin, "%"), Hmax: extreme(summary.Hmax, "%"), Hmoy: reading(summary.Hmoy, "%")
};
return [null, msg];
